<!doctype html><html lang="nb"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kvittering {{ $payment->terminal_reference }}</title><style>*{box-sizing:border-box}body{margin:0;background:#eef3f0;color:#10231b;font:15px/1.5 Arial,sans-serif}.receipt{width:min(80mm,calc(100% - 24px));margin:28px auto;background:#fff;padding:9mm;box-shadow:0 10px 35px #173d2c22}.brand{font-size:19px;font-weight:900}.muted{color:#687970}.amount{margin:22px 0;font-size:30px;font-weight:900}.rows{display:grid;gap:8px}.row{display:flex;justify-content:space-between;gap:18px;border-bottom:1px solid #e1e8e4;padding-bottom:7px}.row span:last-child{text-align:right;font-weight:700}.paid{margin:22px 0 0;padding:12px;background:#e2f5e9;color:#14633e;font-weight:800;text-align:center}.print{display:block;width:min(80mm,calc(100% - 24px));margin:0 auto 28px;border:0;border-radius:10px;background:#16764c;padding:13px;color:#fff;font-weight:800;cursor:pointer}@media print{body{background:#fff}.receipt{width:80mm;margin:0;box-shadow:none}.print{display:none}@page{size:80mm auto;margin:0}}</style><script src="{{ asset('receipt-print.js') }}" defer></script></head><body>
<article class="receipt"><div class="brand">{{ $payment->booking->customer?->organization?->name ?? 'DekkPilot' }}</div><div class="muted">Kvittering {{ $payment->terminal_reference }}</div><div class="amount">{{ number_format($payment->amount_cents/100,2,',',' ') }} kr</div><div class="rows"><div class="row"><span>Dato</span><span>{{ $payment->paid_at->format('d.m.Y H:i') }}</span></div><div class="row"><span>Kunde</span><span>{{ $payment->booking->customer?->name }}</span></div><div class="row"><span>Reg.nr.</span><span>{{ $payment->booking->vehicle?->registration_number }}</span></div><div class="row"><span>Tjeneste</span><span>{{ $payment->booking->service_name }}</span></div><div class="row"><span>Betalt med</span><span>{{ ['vipps'=>'Vipps','cash'=>'Kontant','terminal'=>'Bankterminal'][$payment->payment_method] ?? ucfirst((string)$payment->payment_method) }}</span></div><div class="row"><span>Transaksjon</span><span>{{ $payment->provider_reference }}</span></div></div><div class="paid">✓ BETALT</div></article><button class="print" type="button" data-print-receipt>Skriv ut kvittering</button></body></html>
